insert into public.institutional_section_variants (id, section_type, name, description, owner_user_id, is_system, visibility, status)
values
  ('c1400000-0000-4000-8000-000000000001', 'organization_intro', 'Narrativa humana', 'Hero editorial com imagem dominante, mensagem clara e chamadas para ação.', null, true, 'public', 'published'),
  ('c1400000-0000-4000-8000-000000000002', 'organization_intro', 'Manifesto editorial', 'Título amplo, texto de apoio e imagem panorâmica para uma entrada mais expressiva.', null, true, 'public', 'published'),
  ('c1400000-0000-4000-8000-000000000003', 'organization_about', 'História editorial', 'Uma composição com fotografia e narrativa para apresentar identidade, território e trajetória.', null, true, 'public', 'published'),
  ('c1400000-0000-4000-8000-000000000004', 'projects_showcase', 'Mosaico de iniciativas', 'Cards editoriais com fotografia e informação suficiente para entender cada projeto rapidamente.', null, true, 'public', 'published'),
  ('c1400000-0000-4000-8000-000000000005', 'impact_metrics', 'Faixa de impacto', 'Indicadores amplos e fáceis de escanear, com contexto e período quando necessário.', null, true, 'public', 'published'),
  ('c1400000-0000-4000-8000-000000000006', 'support_actions', 'Convites para participar', 'Formas de apoio apresentadas como caminhos claros e comparáveis.', null, true, 'public', 'published'),
  ('c1400000-0000-4000-8000-000000000007', 'transparency', 'Painel de confiança', 'Documentos e informações organizados em blocos de leitura rápida.', null, true, 'public', 'published'),
  ('c1400000-0000-4000-8000-000000000008', 'organization_contact', 'Contato acolhedor', 'Canais e informações de atendimento em uma composição curta e direta.', null, true, 'public', 'published'),
  ('c1400000-0000-4000-8000-000000000009', 'site_footer', 'Rodapé editorial', 'Rodapé robusto com identidade, contato, redes e texto final.', null, true, 'public', 'published'),
  ('c1400000-0000-4000-8000-000000000010', 'custom_content', 'Como funciona', 'Uma sequência visual de etapas para explicar atendimento, participação ou outro processo.', null, true, 'public', 'published'),
  ('c1400000-0000-4000-8000-000000000011', 'custom_content', 'Públicos e participação', 'Cards para explicar quem a organização atende e quem pode participar.', null, true, 'public', 'published'),
  ('c1400000-0000-4000-8000-000000000012', 'custom_content', 'História em destaque', 'Bloco editorial para uma história, depoimento ou caso autorizado.', null, true, 'public', 'published')
